// 转发到本机 DSH profile 里真正的 schemastery。
//
// ★ 2026-10-12 改成运行时解析：早先这里写死了一个绝对路径
//   （`file:///C:/Users/<用户名>/.dsh/profiles/desktop/node_modules/...`）——
//   换台机器 clone 下来，这份桩会直接指向一个不存在的地方，自测必崩；
//   而且把使用者的目录结构写进了源码。
//
// 现在**运行时算**：认 $DSH_HOME，没有才回退 ~/.dsh（与插件本体同一套规则）。
//
// ⚠️ 为什么不能写成 `export * from <变量>`：
//   ESM 的 `export ... from` **只吃字符串字面量**（静态分析要求），
//   传变量是**语法错误**（2026-10-12 实测：`SyntaxError: Unexpected identifier`）。
//   所以这里用 `import()` 动态加载，再把要用的东西显式转出去。
//   插件只用到 `z.object` 与各字段的 `.default()`，显式转发足够。
import { join } from 'node:path';
import { homedir } from 'node:os';
import { existsSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const HOME_DSH = (process.env.DSH_HOME ?? '').trim() || join(homedir(), '.dsh');
const TARGET = join(HOME_DSH, 'profiles', 'desktop', 'node_modules',
  '@deepseek-ai', 'schemastery', 'lib', 'index.mjs');

if (!existsSync(TARGET)) {
  // 找不到真身时**响亮失败**，别静默给个空模块 —— 那会让自测"全绿"着骗人。
  throw new Error(
    `本机找不到真的 schemastery：${TARGET}\n` +
    '这份是测试用的转发桩，它需要一个装好的 DSH profile。\n' +
    '如果只是想跑自测，先确认 DSH_HOME 指向正确的 .dsh 目录。'
  );
}

const mod = await import(pathToFileURL(TARGET).href);

// 显式转发（插件实际用到的就是这些）
export const z = mod.z ?? mod.default ?? mod;
export default mod.default ?? mod;
